import { useEffect, useReducer, useState } from "react";
import axios from "../app/api/axios";
import initialState from "../store";
import reducer from "../reducer";

const Register = () => {
  const [state, dispatch] = useReducer(reducer, initialState);

  const getUsers = async () => {
    const response = await axios.get("/register");
    console.log(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newUser = {
      username: state.username,
      email: state.email,
      pwd: state.pwd,
    };
    console.log(newUser);
    // const response = await axios.post("/register", newUser);
  };

  // useEffect(() => {
  //   getUsers();
  // }, []);

  return (
    <div className="register">
      <h3>Register</h3>
      <form className="register-form" onSubmit={handleSubmit}>
        <label>name</label>
        <input
          value={state.username}
          type="text"
          onChange={(e) =>
            dispatch({ type: "USERNAME", paylaod: e.target.value })
          }
        />
        <label>email</label>
        <input
          value={state.email}
          type="text"
          onChange={(e) => dispatch({ type: "EMAIL", paylaod: e.target.value })}
        />
        <label>password</label>
        <input
          value={state.pwd}
          type="text"
          onChange={(e) => dispatch({ type: "PWD", paylaod: e.target.value })}
        />
        <label>confrirm password</label>
        <input
          value={state.confirmPwd}
          type="text"
          onChange={(e) =>
            dispatch({ type: "CONFIRMPWD", paylaod: e.target.value })
          }
        />
        <br />
        <button type="submit">sign up</button>
      </form>
    </div>
  );
};

export default Register;
